import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { storiesAPI, scrapeAPI } from '../services/api';
import { Bookmark, ExternalLink, RefreshCw, User } from 'lucide-react';

interface Story {
  _id: string;
  title: string;
  url: string;
  points: number;
  author: string;
  postedAt: string;
  hackerNewsId: string;
  isBookmarked?: boolean;
}

interface PaginationInfo {
  page: number;
  limit: number;
  total: number;
  pages: number;
}

const Home: React.FC = () => {
  const [stories, setStories] = useState<Story[]>([]);
  const [pagination, setPagination] = useState<PaginationInfo | null>(null);
  const [loading, setLoading] = useState(true);
  const [scraping, setScraping] = useState(false);
  const [error, setError] = useState('');
  const [currentPage, setCurrentPage] = useState(1);

  const { isAuthenticated } = useAuth();

  const fetchStories = async (page: number = 1) => {
    try {
      setLoading(true);
      const response = await storiesAPI.getStories(page, 10);
      setStories(response.data.stories);
      setPagination(response.data.pagination);
      setCurrentPage(page);
    } catch (err: any) {
      setError('Failed to fetch stories');
    } finally {
      setLoading(false);
    }
  };

  const handleScrape = async () => {
    try {
      setScraping(true);
      await scrapeAPI.scrape();
      await fetchStories(currentPage);
    } catch (err: any) {
      setError('Failed to scrape new stories');
    } finally {
      setScraping(false);
    }
  };

  const handleBookmark = async (storyId: string) => {
    if (!isAuthenticated) return;

    try {
      await storiesAPI.toggleBookmark(storyId);
      await fetchStories(currentPage);
    } catch (err: any) {
      setError('Failed to toggle bookmark');
    }
  };

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffInHours = Math.floor((now.getTime() - date.getTime()) / (1000 * 60 * 60));

    if (diffInHours < 1) {
      const diffInMinutes = Math.floor((now.getTime() - date.getTime()) / (1000 * 60));
      return `${diffInMinutes} minute${diffInMinutes !== 1 ? 's' : ''} ago`;
    } else if (diffInHours < 24) {
      return `${diffInHours} hour${diffInHours !== 1 ? 's' : ''} ago`;
    } else {
      const diffInDays = Math.floor(diffInHours / 24);
      return `${diffInDays} day${diffInDays !== 1 ? 's' : ''} ago`;
    }
  };

  useEffect(() => {
    fetchStories();
  }, []);

  return (
    <div>
      <div className="flex justify-between items-center mb-8">
        <h1 className="text-3xl font-bold text-gray-900">Top Stories</h1>
        <button
          onClick={handleScrape}
          disabled={scraping}
          className="flex items-center space-x-2 bg-orange-600 text-white px-4 py-2 rounded-md hover:bg-orange-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
        >
          <RefreshCw size={18} className={scraping ? 'animate-spin' : ''} />
          <span>{scraping ? 'Scraping...' : 'Refresh Stories'}</span>
        </button>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-md mb-6">
          {error}
        </div>
      )}

      {loading ? (
        <div className="flex justify-center items-center h-64">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-orange-600"></div>
        </div>
      ) : (
        <>
          <div className="space-y-4">
            {stories.map((story, index) => (
              <div key={story._id} className="bg-white rounded-lg shadow-sm border border-gray-200 p-4 hover:shadow-md transition-shadow">
                <div className="flex items-start space-x-3">
                  <span className="text-gray-500 font-medium text-sm w-6">{index + 1}.</span>

                  <div className="flex-1">
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <h3 className="text-lg font-medium text-gray-900 mb-1">
                          <a
                            href={story.url}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="hn-link hover:text-orange-600 flex items-center space-x-1"
                          >
                            <span>{story.title}</span>
                            <ExternalLink size={14} className="text-gray-400" />
                          </a>
                        </h3>

                        <div className="hn-meta flex items-center space-x-4 text-sm">
                          <span className="flex items-center space-x-1">
                            <span className="font-medium">{story.points}</span>
                            <span>points</span>
                          </span>

                          <span className="flex items-center space-x-1">
                            <User size={14} />
                            <span>{story.author}</span>
                          </span>

                          <span>{formatDate(story.postedAt)}</span>
                        </div>
                      </div>

                      {isAuthenticated && (
                        <button
                          onClick={() => handleBookmark(story._id)}
                          className="bookmark-btn ml-4 p-2 rounded-full hover:bg-gray-100"
                          title="Toggle bookmark"
                        >
                          <Bookmark 
                            size={18} 
                            className={story.isBookmarked ? 'bookmarked fill-current' : ''}
                          />
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {pagination && pagination.pages > 1 && (
            <div className="flex justify-center items-center space-x-2 mt-8">
              <button
                onClick={() => fetchStories(currentPage - 1)}
                disabled={currentPage === 1}
                className="px-3 py-1 rounded-md border border-gray-300 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Previous
              </button>

              <span className="text-gray-600">
                Page {currentPage} of {pagination.pages}
              </span>

              <button
                onClick={() => fetchStories(currentPage + 1)}
                disabled={currentPage === pagination.pages}
                className="px-3 py-1 rounded-md border border-gray-300 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Next
              </button>
            </div>
          )}

          {!isAuthenticated && stories.length > 0 && (
            <div className="mt-8 text-center">
              <p className="text-gray-600">
                <Link to="/register" className="text-orange-600 hover:text-orange-700 font-medium">
                  Create an account
                </Link>
                {' '}to bookmark your favorite stories
              </p>
            </div>
          )}
        </>
      )}
    </div>
  );
};

export default Home;
